module suspect_pair_counter #(\n    parameter N_MAX = 10\n)(\n    input [3:0] n,\n    input [3:0] p,\n    input [3:0] x0, y0,\n    input [3:0] x1, y1,\n    input [3:0] x2, y2,\n    input [3:0] x3, y3,\n    input [3:0] x4, y4,\n    input [3:0] x5, y5,\n    input [3:0] x6, y6,\n    input [3:0] x7, y7,\n    input [3:0] x8, y8,\n    input [3:0] x9, y9,\n    output reg [5:0] result\n);\n\n    reg [3:0] deg [0:N_MAX-1];\n    reg [3:0] edge_cnt [0:N_MAX-1][0:N_MAX-1];\n\n    integer i, j, a, b;\n\n    always @(*) begin\n        // Initialize deg and edge_cnt\n        for (i = 0; i < N_MAX; i = i + 1) begin\n            deg[i] = 4'b0;\n            for (j = 0; j < N_MAX; j = j + 1) begin\n                edge_cnt[i][j] = 4'b0;\n            end\n        end\n\n        // Process each coder\n        for (i = 0; i < N_MAX; i = i + 1) begin\n            if (i < n) begin\n                reg [3:0] x, y;\n                case (i)\n                    0: begin x = x0 - 4'd1; y = y0 - 4'd1; end\n                    1: begin x = x1 - 4'd1; y = y1 - 4'd1; end\n                    2: begin x = x2 - 4'd1; y = y2 - 4'd1; end\n                    3: begin x = x3 - 4'd1; y = y3 - 4'd1; end\n                    4: begin x = x4 - 4'd1; y = y4 - 4'd1; end\n                    5: begin x = x5 - 4'd1; y = y5 - 4'd1; end\n                    6: begin x = x6 - 4'd1; y = y6 - 4'd1; end\n                    7: begin x = x7 - 4'd1; y = y7 - 4'd1; end\n                    8: begin x = x8 - 4'd1; y = y8 - 4'd1; end\n                    9: begin x = x9 - 4'd1; y = y9 - 4'd1; end\n                    default: begin x = 4'b0; y = 4'b0; end\n                endcase\n\n                deg[x] = deg[x] + 4'd1;\n                deg[y] = deg[y] + 4'd1;\n\n                if (x < y) begin\n                    edge_cnt[x][y] = edge_cnt[x][y] + 4'd1;\n                end else if (y < x) begin\n                    edge_cnt[y][x] = edge_cnt[y][x] + 4'd1;\n                end\n            end\n        end\n\n        // Count valid pairs\n        result = 6'd0;\n        for (a = 0; a < N_MAX; a = a + 1) begin\n            if (a < n) begin\n                for (b = a + 1; b < N_MAX; b = b + 1) begin\n                    if (b < n) begin\n                        reg [5:0] agreement;\n                        agreement = deg[a] + deg[b] - edge_cnt[a][b];\n                        if (agreement >= {2'b00, p}) begin\n                            result = result + 6'd1;\n                        end\n                    end\n                end\n            end\n        end\n    end\n\nendmodule